local TemperingFurnaceMaker = {}
local PRODUCTS = {
    simple_brick_tempering_furnace = { name = "Preprosta opečna kalilna peč", brickCost = 4, ironCost = 2, clayCost = 1, time = 7, cost = 280, science = 25, happiness = 1, description = "Preprosta opečna kalilna peč za kaljenje kovin." },
    iron_reinforced_tempering_furnace = { name = "Železnookrepljena kalilna peč", brickCost = 3, ironCost = 3, clayCost = 1, time = 10, cost = 640, science = 38, happiness = 2, prestige = 2, description = "Železnookrepljena kalilna peč za trgovce." },
    silver_banded_tempering_furnace = { name = "Srebrnopasna kalilna peč", brickCost = 3, silverCost = 1, ironCost = 3, clayCost = 1, time = 14, cost = 1450, science = 52, happiness = 2, prestige = 6, description = "Srebrnopasna kalilna peč za plemiče." },
    gold_trimmed_tempering_furnace = { name = "Zlatookrasna kalilna peč", brickCost = 3, goldCost = 1, silverCost = 1, ironCost = 3, clayCost = 1, time = 18, cost = 3200, science = 68, happiness = 3, prestige = 14, description = "Zlatookrasna kalilna peč za visoke plemiče." },
    jewel_set_tempering_furnace = { name = "Draguljasta kalilna peč", brickCost = 3, goldCost = 1, silverCost = 1, ironCost = 3, clayCost = 1, jewelCost = 1, time = 22, cost = 6800, science = 82, happiness = 5, prestige = 27, description = "Kalilna peč z draguljem za visoko plemstvo." },
    royal_grand_tempering_furnace = { name = "Kraljevski veliki kalilna peč", brickCost = 5, goldCost = 2, silverCost = 2, ironCost = 3, clayCost = 1, jewelCost = 2, pearlCost = 2, time = 29, cost = 14000, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska kalilna peč z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    tempering_workshop = { name = "Kalilna delavnica", cost = { gold = 320, wood = 140, stone = 180, brick = 8, iron = 6 }, upkeep = 7, qualityBonus = 5 },
    metallurgy_loft = { name = "Metalurška podstrešje", cost = { gold = 1100, wood = 320, stone = 320, silver = 6, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_tempering_atelier = { name = "Mojstrski kalilni atelje", cost = { gold = 2800, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 65, qualityBonus = 30 },
    royal_metallurgy_palace = { name = "Kraljevska metalurška palača", cost = { gold = 12000, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
TemperingFurnaceMaker.brickStock = 18; TemperingFurnaceMaker.ironStock = 14; TemperingFurnaceMaker.clayStock = 10; TemperingFurnaceMaker.silverStock = 6; TemperingFurnaceMaker.goldStock = 6; TemperingFurnaceMaker.jewelStock = 4; TemperingFurnaceMaker.pearlStock = 4
TemperingFurnaceMaker.productStock = {}; TemperingFurnaceMaker.buildings = {}; TemperingFurnaceMaker.maker = nil; TemperingFurnaceMaker.activeMaking = {}; TemperingFurnaceMaker.totalProducts = 0; TemperingFurnaceMaker.dayTimer = 0
function TemperingFurnaceMaker.init() TemperingFurnaceMaker.brickStock=18; TemperingFurnaceMaker.ironStock=14; TemperingFurnaceMaker.clayStock=10; TemperingFurnaceMaker.silverStock=6; TemperingFurnaceMaker.goldStock=6; TemperingFurnaceMaker.jewelStock=4; TemperingFurnaceMaker.pearlStock=4; TemperingFurnaceMaker.productStock={}; TemperingFurnaceMaker.buildings={}; TemperingFurnaceMaker.maker=nil; TemperingFurnaceMaker.activeMaking={}; TemperingFurnaceMaker.totalProducts=0; TemperingFurnaceMaker.dayTimer=0; print("[TemperingFurnaceMaker] Royal Tempering Furnace Maker System initialized (6 products, 4 buildings)") end
function TemperingFurnaceMaker.hireMaker(n,s) s=s or math.random(55,90); local c=620+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TemperingFurnaceMaker.maker={name=n or ("Kalilni pečar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kalilni pečar najet: %s (spretnost: %d)",TemperingFurnaceMaker.maker.name,s),"success") end; return true end
function TemperingFurnaceMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TemperingFurnaceMaker.build(id) local ok,e=TemperingFurnaceMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TemperingFurnaceMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TemperingFurnaceMaker.getQualityBonus() local b=0; for _,bd in ipairs(TemperingFurnaceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TemperingFurnaceMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brickCost and TemperingFurnaceMaker.brickStock<(d.brickCost or 0) then return false,"Premalo opek" end; if d.ironCost and TemperingFurnaceMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.clayCost and TemperingFurnaceMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.silverCost and TemperingFurnaceMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TemperingFurnaceMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TemperingFurnaceMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TemperingFurnaceMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TemperingFurnaceMaker.buildings==0 then return false,"Potrebna kalilna delavnica" end; if not TemperingFurnaceMaker.maker then return false,"Potreben kalilni pečar" end; return true end
function TemperingFurnaceMaker.make(pt,qty) qty=qty or 1; local ok,e=TemperingFurnaceMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brickCost then TemperingFurnaceMaker.brickStock=TemperingFurnaceMaker.brickStock-d.brickCost*qty end; if d.ironCost then TemperingFurnaceMaker.ironStock=TemperingFurnaceMaker.ironStock-d.ironCost*qty end; if d.clayCost then TemperingFurnaceMaker.clayStock=TemperingFurnaceMaker.clayStock-d.clayCost*qty end; if d.silverCost then TemperingFurnaceMaker.silverStock=TemperingFurnaceMaker.silverStock-d.silverCost*qty end; if d.goldCost then TemperingFurnaceMaker.goldStock=TemperingFurnaceMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TemperingFurnaceMaker.jewelStock=TemperingFurnaceMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TemperingFurnaceMaker.pearlStock=TemperingFurnaceMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TemperingFurnaceMaker.maker then t=math.max(1,t-math.floor(TemperingFurnaceMaker.maker.skill/12)) end; table.insert(TemperingFurnaceMaker.activeMaking,{id="temperingfurnace_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TemperingFurnaceMaker.completeMaking(m) local q=1.0+(TemperingFurnaceMaker.getQualityBonus()/100); if TemperingFurnaceMaker.maker then q=q+(TemperingFurnaceMaker.maker.skill/140) end; q=math.min(2.5,q); TemperingFurnaceMaker.productStock[m.productType]=(TemperingFurnaceMaker.productStock[m.productType] or 0)+m.quantity; TemperingFurnaceMaker.totalProducts=TemperingFurnaceMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TemperingFurnaceMaker.maker then TemperingFurnaceMaker.maker.itemsMade=TemperingFurnaceMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TemperingFurnaceMaker.maker.skill=math.min(100,TemperingFurnaceMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kalilna peč izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"temperingfurnace.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function TemperingFurnaceMaker.update(dt) if not _G.state then return end; TemperingFurnaceMaker.dayTimer=TemperingFurnaceMaker.dayTimer+dt; if TemperingFurnaceMaker.dayTimer>=30 then TemperingFurnaceMaker.dayTimer=0; for i=#TemperingFurnaceMaker.activeMaking,1,-1 do local m=TemperingFurnaceMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TemperingFurnaceMaker.completeMaking(m); table.remove(TemperingFurnaceMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TemperingFurnaceMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TemperingFurnaceMaker.maker then tu=tu+17 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TemperingFurnaceMaker.getStats() return {brickStock=TemperingFurnaceMaker.brickStock,ironStock=TemperingFurnaceMaker.ironStock,clayStock=TemperingFurnaceMaker.clayStock,silverStock=TemperingFurnaceMaker.silverStock,goldStock=TemperingFurnaceMaker.goldStock,jewelStock=TemperingFurnaceMaker.jewelStock,pearlStock=TemperingFurnaceMaker.pearlStock,productStock=TemperingFurnaceMaker.productStock,numBuildings=#TemperingFurnaceMaker.buildings,hasMaker=TemperingFurnaceMaker.maker~=nil,makerName=TemperingFurnaceMaker.maker and TemperingFurnaceMaker.maker.name or "—",makerSkill=TemperingFurnaceMaker.maker and TemperingFurnaceMaker.maker.skill or 0,activeMaking=#TemperingFurnaceMaker.activeMaking,totalProducts=TemperingFurnaceMaker.totalProducts} end
return TemperingFurnaceMaker
